40	```c
41	#ifndef __DRIVERS_NET_CVITEK_ETH_H
42	#define __DRIVERS_NET_CVITEK_ETH_H
43	
44	#include <nuttx/config.h>
45	#include <nuttx/net/netdev.h>
46	#include <stdint.h>
47	
48	/* ===== 1. 基地址 (来源: 设备树) ===== */
49	#define CVITEK_GMAC_BASE    0x04070000   /* 设备树: reg */
50	#define CVITEK_EPHY_BASE    0x03009000   /* 设备树: ephy_base_reg */
51	#define CVITEK_EPHY_TOP     0x03009800   /* 设备树: ephy_top_reg  */
52	
53	/* ===== 2. GMAC 寄存器偏移 (来源: dwmac4.h) ===== */
54	#define GMAC_CONFIG             0x0000
55	#define GMAC_PACKET_FILTER      0x0008
56	#define GMAC_INT_STATUS         0x00B0
57	#define GMAC_INT_EN             0x00B4
58	#define GMAC_HW_FEATURE0        0x011C
59	#define GMAC_MDIO_ADDR          0x0200
60	#define GMAC_MDIO_DATA          0x0204
61	#define GMAC_ADDR_HIGH(n)       (0x0300 + (n) * 8)
62	#define GMAC_ADDR_LOW(n)        (0x0304 + (n) * 8)
63	
64	/* ===== 3. GMAC_CONFIG bit 位 (来源: dwmac4.h + dwmac1000.h) ===== */
65	#define GMAC_CONFIG_RE          (1 << 0)
66	#define GMAC_CONFIG_TE          (1 << 1)
67	#define GMAC_CONFIG_DCRS        (1 << 9)
68	#define GMAC_CONFIG_DM          (1 << 13)
69	#define GMAC_CONFIG_FES         (1 << 14)
70	#define GMAC_CONFIG_PS          (1 << 15)
71	#define GMAC_CONFIG_BE          (1 << 18)
72	#define GMAC_CONFIG_JD          (1 << 17)
73	#define GMAC_CONFIG_JE          (1 << 16)
74	#define GMAC_CONFIG_ACS         (1 << 20)
75	#define GMAC_CORE_INIT  (GMAC_CONFIG_JD | GMAC_CONFIG_PS | \
76	                         GMAC_CONFIG_ACS | GMAC_CONFIG_BE | GMAC_CONFIG_DCRS)
77	
78	/* ===== 4. 包过滤 (来源: dwmac4.h) ===== */
79	#define GMAC_FILTER_PR          (1 << 0)
80	#define GMAC_FILTER_HMC         (1 << 2)
81	#define GMAC_FILTER_PM          (1 << 4)
82	#define GMAC_FILTER_RA          (1 << 31)
83	
84	/* ===== 5. MDIO (来源: dwmac1000.h) ===== */
85	#define GMAC_MDIO_BUSY          (1 << 0)
86	#define GMAC_MDIO_WRITE         (1 << 2)
87	
88	/* ===== 6. MAC 地址寄存器 AE bit (来源: dwmac4.h) ===== */
89	#define GMAC_HI_REG_AE          (1 << 31)
90	
91	/* ===== 7. MAC 中断 (来源: dwmac4.h) ===== */
92	#define GMAC_INT_PMT_EN         (1 << 4)
93	#define GMAC_INT_LPI_EN         (1 << 5)
94	#define GMAC_INT_DEFAULT        (GMAC_INT_PMT_EN | GMAC_INT_LPI_EN)
95	
96	/* ===== 8. DMA 寄存器 (来源: dwmac4_dma.h) ===== */
97	#define DMA_BUS_MODE            0x1000
98	#define DMA_SYS_BUS_MODE        0x1004
99	#define DMA_STATUS              0x1008
100	#define DMA_CHAN_BASE           0x1100
101	#define DMA_CHAN_CONTROL        0x0000
102	#define DMA_CHAN_TX_CONTROL     0x0004
103	#define DMA_CHAN_RX_CONTROL     0x0008
104	#define DMA_CHAN_TX_BASE_ADDR   0x0014
105	#define DMA_CHAN_RX_BASE_ADDR   0x001C
106	#define DMA_CHAN_TX_END_ADDR    0x0020
107	#define DMA_CHAN_RX_END_ADDR    0x0028
108	#define DMA_CHAN_TX_RING_LEN    0x002C
109	#define DMA_CHAN_RX_RING_LEN    0x0030
110	#define DMA_CHAN_INTR_ENA       0x0034
111	#define DMA_CHAN_STATUS         0x0060
112	
113	/* ===== 9. DMA 控制 bit 位 (来源: dwmac4_dma.h) ===== */
114	#define DMA_SFT_RESET           (1 << 0)
115	#define DMA_SYS_FB              (1 << 0)
116	#define DMA_SYS_AAL             (1 << 12)
117	#define DMA_SYS_BLEN16          (1 << 3)
118	#define DMA_SYS_DEFAULT         (DMA_SYS_FB | DMA_SYS_AAL | DMA_SYS_BLEN16)
119	#define DMA_TX_ST               (1 << 0)
120	#define DMA_RX_SR               (1 << 0)
121	
122	/* ===== 10. DMA 中断 (来源: dwmac4_dma.h) ===== */
123	#define DMA_INTR_TIE            (1 << 0)
124	#define DMA_INTR_RIE            (1 << 6)
125	#define DMA_INTR_AIE            (1 << 14)
126	#define DMA_INTR_NIE            (1 << 16)
127	#define DMA_INTR_FBE            (1 << 12)
128	#define DMA_INTR_DEFAULT_MASK   (DMA_INTR_NIE | DMA_INTR_RIE | DMA_INTR_TIE | \
129	                                 DMA_INTR_AIE | DMA_INTR_FBE)
130	#define DMA_STATUS_TI           (1 << 0)
131	#define DMA_STATUS_RI           (1 << 6)
132	#define DMA_STATUS_RBU          (1 << 7)
133	#define DMA_STATUS_TPS          (1 << 1)
134	#define DMA_STATUS_RPS          (1 << 8)
135	#define DMA_STATUS_FBE          (1 << 12)
136	#define DMA_STATUS_AIS          (1 << 14)
137	#define DMA_STATUS_NIS          (1 << 15)
138	
139	/* ===== 11. 描述符 (来源: descs.h) ===== */
140	#define DESC_OWN                (1u << 31)
141	#define TX_DESC_IC              (1 << 30)
142	#define TX_DESC_LS              (1 << 29)
143	#define TX_DESC_FS              (1 << 28)
144	#define RX_DESC_LD              (1 << 8)
145	#define RX_DESC_FD              (1 << 9)
146	#define RX_DESC_ES              (1 << 15)
147	#define RX_DESC_FL_SHIFT        16
148	#define RX_DESC_FL_MASK         0x3FFF
149	
150	/* ===== 12. 环参数 ===== */
151	#define TX_RING_SIZE            64
152	#define RX_RING_SIZE            64
153	#define RX_BUF_SIZE             1536
154	#define TX_BUF_SIZE             1536
155	
156	/* ===== 13. 数据结构 ===== */
157	struct dma_desc {
158	    uint32_t des0;
159	    uint32_t des1;
160	    uint32_t des2;
161	    uint32_t des3;
162	};
163	
164	struct cvitek_eth_priv {
165	    struct net_driver_s dev;
166	    uintptr_t gmac_base;
167	    uintptr_t phy_base;
168	    uintptr_t phy_top;
169	    struct dma_desc *tx_desc;
170	    struct dma_desc *rx_desc;
171	    uint8_t *tx_buf[TX_RING_SIZE];
172	    uint8_t *rx_buf[RX_RING_SIZE];
173	    uint32_t tx_desc_phys;
174	    uint32_t rx_desc_phys;
175	    unsigned int tx_cur;
176	    unsigned int tx_dirty;
177	    unsigned int rx_cur;
178	    uint8_t mac_addr[6];
179	    int irq;
180	};
181	
182	#endif
