280	```c
281	/* 来源: dwmac4_lib.c:15-26 */
282	static int dma_soft_reset(uintptr_t gmac_base)
283	{
284	    uint32_t val;
285	    int timeout = 100000;
286	
287	    val = getreg32(gmac_base + DMA_BUS_MODE);
288	    putreg32(val | DMA_SFT_RESET, gmac_base + DMA_BUS_MODE);
289	
290	    do {
291	        val = getreg32(gmac_base + DMA_BUS_MODE);
292	        if (!(val & DMA_SFT_RESET)) {
293	            printf("DMA reset PASS\n");
294	            return 0;
295	        }
296	        up_udelay(10);
297	    } while (--timeout > 0);
298	
299	    printf("FAIL: DMA reset timeout\n");
300	    return -1;
301	}
302	```
