317	## 步骤 3：EPHY 复位 + MDIO 读 PHY ID
318	
319	### 创建文件
320	
321	无新文件。在 `cvitek_eth.c` 中增加 3 个函数：
322	
323	```c
324	/* 来源: dwmac-cvitek.c:46-117 */
325	static void ephy_hardware_reset(uintptr_t phy_base, uintptr_t phy_top)
326	{
327	    putreg32(0x0001, phy_top + 0x4);       /* APB 选通 */
328	    putreg32(0x0900, phy_top);             /* 释放 shutdown */
329	    putreg32(0x0904, phy_top);             /* 释放 dig_rst_n */
330	    putreg32(0x0500, phy_base + 0x7C);     /* → Page 5 */
331	    putreg32(0x0C00, phy_base + 0x40);     /* ANA_PD */
332	    putreg32(0x0C7E, phy_base + 0x40);     /* ANA_EN */
333	    up_mdelay(1);
334	    putreg32(0x0906, phy_top);             /* 释放 ana_rst_n */
335	    putreg32(0x0500, phy_base + 0x7C);
336	    putreg32(0x0043, phy_base + 0x08);     /* PHY_ID_HIGH */
337	    putreg32(0x5649, phy_base + 0x0C);     /* PHY_ID_LOW */
338	    putreg32(0x0000, phy_top + 0x4);       /* 切回 MDIO 控制 */
339	    up_mdelay(10);
340	}
341	
342	/* 来源: dwmac1000.h:148-149, dwmac4.h:43-44 */
343	static uint16_t mdio_read(uintptr_t gmac_base, int phy_addr, int reg)
344	{
345	    uint32_t val = ((phy_addr & 0x1F) << 11) | ((reg & 0x1F) << 6) | 0x1;
346	    int to = 10000;
347	    putreg32(val, gmac_base + GMAC_MDIO_ADDR);
348	    do { val = getreg32(gmac_base + GMAC_MDIO_ADDR);
349	         if (!(val & 0x1)) return getreg32(gmac_base + GMAC_MDIO_DATA) & 0xFFFF;
350	         up_udelay(1);
351	    } while (--to > 0);
352	    return 0xFFFF;
353	}
354	```
