374	## 步骤 4：分配 DMA 描述符环 + 写 DMA 寄存器
375	
376	### 创建文件
377	
378	无新文件。在 `cvitek_eth.c` 中增加：
379	
380	```c
381	static int alloc_dma(struct cvitek_eth_priv *priv)
382	{
383	    int i;
384	    priv->tx_desc = kmm_memalign(16, TX_RING_SIZE * sizeof(struct dma_desc));
385	    priv->rx_desc = kmm_memalign(16, RX_RING_SIZE * sizeof(struct dma_desc));
386	    if (!priv->tx_desc || !priv->rx_desc) return -ENOMEM;
387	    memset(priv->tx_desc, 0, TX_RING_SIZE * sizeof(struct dma_desc));
388	    memset(priv->rx_desc, 0, RX_RING_SIZE * sizeof(struct dma_desc));
389	    priv->tx_desc_phys = (uint32_t)(uintptr_t)priv->tx_desc;
390	    priv->rx_desc_phys = (uint32_t)(uintptr_t)priv->rx_desc;
391	    for (i = 0; i < TX_RING_SIZE; i++) priv->tx_buf[i] = kmm_memalign(4, TX_BUF_SIZE);
392	    for (i = 0; i < RX_RING_SIZE; i++) priv->rx_buf[i] = kmm_memalign(4, RX_BUF_SIZE);
393	    return 0;
394	}
395	
396	static void init_desc_and_dma(struct cvitek_eth_priv *priv)
397	{
398	    uintptr_t base = priv->gmac_base;
399	    uintptr_t dma = base + DMA_CHAN_BASE;
400	    int i;
401	
402	    /* TX 描述符清零 + RX 描述符 OWN=1 */
403	    for (i = 0; i < TX_RING_SIZE; i++) {
404	        priv->tx_desc[i].des0 = 0;
405	        priv->tx_desc[i].des2 = (uint32_t)(uintptr_t)priv->tx_buf[i];
406	    }
407	    for (i = 0; i < RX_RING_SIZE; i++) {
408	        priv->rx_desc[i].des0 = DESC_OWN;
409	        priv->rx_desc[i].des1 = RX_BUF_SIZE;
410	        priv->rx_desc[i].des2 = (uint32_t)(uintptr_t)priv->rx_buf[i];
411	    }
412	    priv->tx_cur = priv->tx_dirty = priv->rx_cur = 0;
413	
414	    /* 写 DMA 寄存器 */
415	    putreg32(DMA_SYS_DEFAULT, base + DMA_SYS_BUS_MODE);
416	    putreg32(TX_RING_SIZE - 1, dma + DMA_CHAN_TX_RING_LEN);
417	    putreg32(RX_RING_SIZE - 1, dma + DMA_CHAN_RX_RING_LEN);
418	    putreg32(priv->tx_desc_phys, dma + DMA_CHAN_TX_BASE_ADDR);
419	    putreg32(priv->rx_desc_phys, dma + DMA_CHAN_RX_BASE_ADDR);
420	    putreg32(DMA_INTR_DEFAULT_MASK, dma + DMA_CHAN_INTR_ENA);
421	}
422	```
