462	## 步骤 5：配置 MAC + 启动 DMA + 发测试包
463	
464	### 创建文件
465	
466	无新文件。在 `cvitek_eth.c` 中增加：
467	
468	```c
469	/* 来源: dwmac4_lib.c:187-201 */
470	static void set_mac_addr(uintptr_t gmac_base, const uint8_t *mac)
471	{
472	    uint32_t hi = (mac[5] << 8) | mac[4] | GMAC_HI_REG_AE;
473	    uint32_t lo = (mac[3] << 24) | (mac[2] << 16) | (mac[1] << 8) | mac[0];
474	    putreg32(hi, gmac_base + GMAC_ADDR_HIGH(0));
475	    putreg32(lo, gmac_base + GMAC_ADDR_LOW(0));
476	}
477	
478	/* 来源: dwmac4_core.c:48 + dwmac4_lib.c:38-73 */
479	static void start_mac_and_dma(uintptr_t gmac_base)
480	{
481	    uintptr_t dma = gmac_base + DMA_CHAN_BASE;
482	    uint32_t v;
483	
484	    v = GMAC_CORE_INIT | GMAC_CONFIG_FES | GMAC_CONFIG_DM;
485	    putreg32(v, gmac_base + GMAC_CONFIG);
