513	static int send_packet(struct cvitek_eth_priv *priv, const uint8_t *data, int len)
514	{
515	    unsigned int idx = priv->tx_cur;
516	    struct dma_desc *desc = &priv->tx_desc[idx];
517	
518	    if (desc->des0 & DESC_OWN) { printf("TX ring full\n"); return -EBUSY; }
519	
520	    memcpy(priv->tx_buf[idx], data, len);
521	    desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
522	    desc->des1 = len;
523	    desc->des0 = DESC_OWN | TX_DESC_FS | TX_DESC_LS | TX_DESC_IC | len;
524	    priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);
