590	```c
591	/* 来源: dwmac4_lib.c:141-184 */
592	static int cvitek_eth_isr(int irq, void *context, void *arg)
593	{
594	    struct cvitek_eth_priv *priv = (struct cvitek_eth_priv *)arg;
595	    uintptr_t base = priv->gmac_base;
596	    uintptr_t dma  = base + DMA_CHAN_BASE;
597	    uint32_t status, intr_en;
598	    uint32_t mac = getreg32(base + GMAC_INT_STATUS);
599	    if (mac) putreg32(mac, base + GMAC_INT_STATUS);
600	
601	    intr_en = getreg32(dma + DMA_CHAN_INTR_ENA);
602	    status  = getreg32(dma + DMA_CHAN_STATUS) & intr_en;
603	    if (!status) return OK;
604	
605	    putreg32(status, dma + DMA_CHAN_STATUS);  /* W1C 清除 */
606	
607	    if (status & DMA_STATUS_NIS) {
608	        if (status & DMA_STATUS_RI)
609	            netdev_rx_ready(&priv->dev);       /* 有包 → 通知 NuttX */
610	        if (status & DMA_STATUS_TI)
611	            /* TX 完成 */;
612	    }
613	    if (status & DMA_STATUS_AIS) {
614	        printf("!! DMA Abnormal: 0x%08X\n", status);
615	        if (status & DMA_STATUS_RBU) printf("   RX Buf Unavailable\n");
616	        if (status & DMA_STATUS_TPS) printf("   TX Stopped\n");
617	        if (status & DMA_STATUS_FBE) printf("   Fatal Bus Error\n");
618	    }
619	    return OK;
620	}
621	
622	/* RX 接收 */
623	static int cvitek_eth_rx(struct cvitek_eth_priv *priv)
624	{
625	    struct dma_desc *desc = &priv->rx_desc[priv->rx_cur];
626	
627	    if (desc->des0 & DESC_OWN) return 0;   /* 空 */
628	
629	    uint32_t status = desc->des0;
630	    if (status & RX_DESC_ES) goto refill;   /* 错误包丢弃 */
631	
632	    int len = ((status >> RX_DESC_FL_SHIFT) & RX_DESC_FL_MASK) - 4;  /* 去 FCS */
633	    if (len > CONFIG_NET_ETH_PKTSIZE) len = CONFIG_NET_ETH_PKTSIZE;
634	    memcpy(priv->dev.d_buf, priv->rx_buf[priv->rx_cur], len);
635	    priv->dev.d_len = len;
636	
637	refill:
638	    desc->des0 = DESC_OWN;
639	    desc->des1 = RX_BUF_SIZE;
640	    priv->rx_cur = (priv->rx_cur + 1) & (RX_RING_SIZE - 1);
641	    rx_doorbell(priv);
642	    return (priv->dev.d_len > 0) ? 1 : 0;
643	}
