685	static int cvitek_ifup(struct net_driver_s *dev)
686	{
687	    struct cvitek_eth_priv *priv = (struct cvitek_eth_priv *)dev->d_private;
688	    ephy_hardware_reset(priv->phy_base, priv->phy_top);
689	    dma_soft_reset(priv->gmac_base);
690	    init_desc_and_dma(priv);
691	    set_mac_addr(priv->gmac_base, priv->mac_addr);
692	    start_mac_and_dma(priv->gmac_base);
693	    rx_doorbell(priv);
694	    up_enable_irq(priv->irq);
695	    netdev_carrier_on(dev);
696	    return OK;
697	}
698	
699	static int cvitek_ifdown(struct net_driver_s *dev)
700	{
701	    struct cvitek_eth_priv *priv = (struct cvitek_eth_priv *)dev->d_private;
702	    up_disable_irq(priv->irq);
703	    putreg32(getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL) & ~DMA_TX_ST,
704	             priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL);
705	    putreg32(getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL) & ~DMA_RX_SR,
706	             priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);
707	    uint32_t v = getreg32(priv->gmac_base + GMAC_CONFIG);
708	    putreg32(v & ~(GMAC_CONFIG_TE | GMAC_CONFIG_RE), priv->gmac_base + GMAC_CONFIG);
709	    netdev_carrier_off(dev);
710	    return OK;
711	}
712	
713	static int cvitek_txavail(struct net_driver_s *dev)
714	{
715	    struct cvitek_eth_priv *priv = (struct cvitek_eth_priv *)dev->d_private;
716	    if (dev->d_len > 0) {
717	        send_packet(priv, dev->d_buf, dev->d_len);
718	        dev->d_len = 0;
719	        NETDEV_TXPACKETS(dev);
720	    }
721	    return OK;
722	}
723	
724	static int cvitek_rmac(struct net_driver_s *dev)
725	{
726	    struct cvitek_eth_priv *priv = (struct cvitek_eth_priv *)dev->d_private;
727	    if (cvitek_eth_rx(priv))
728	        NETDEV_RXPACKETS(dev);
729	    return OK;
730	}
