740	    priv->phy_top   = 0x03009800;
741	    /* MAC 地址: 生产环境应从 eFuse/OTP 读取 */
742	    priv->mac_addr[0] = 0x02; priv->mac_addr[5] = 0x01;
743	
744	    if (alloc_dma(priv) < 0) { kmm_free(priv); return -ENOMEM; }
745	
746	    priv->dev.d_ifup    = cvitek_ifup;
747	    priv->dev.d_ifdown  = cvitek_ifdown;
748	    priv->dev.d_txavail = cvitek_txavail;
749	    priv->dev.d_rmac    = cvitek_rmac;
750	    priv->dev.d_private = priv;
