  printf("PASS\n");
  return 0;
}

/****************************************************************************
 * Private Functions - Step 2: DMA Software Reset
 ****************************************************************************/

/****************************************************************************
 * Name: dma_soft_reset
 *
 * Description:
 *   Perform DMA software reset.
 *   Source: dwmac4_lib.c:15-26
 *
 ****************************************************************************/

static int dma_soft_reset(uintptr_t gmac_base)
{
  uint32_t val;
  int timeout = 100000;

  val = getreg32(gmac_base + DMA_BUS_MODE);
  putreg32(val | DMA_SFT_RESET, gmac_base + DMA_BUS_MODE);

  do
    {
      val = getreg32(gmac_base + DMA_BUS_MODE);
      if (!(val & DMA_SFT_RESET))
        {
          printf("DMA reset PASS\n");
          return 0;
        }

      up_udelay(10);
    }
  while (--timeout > 0);

  printf("FAIL: DMA reset timeout\n");
  return -1;
}

