211	/****************************************************************************
212	 * Name: alloc_dma
213	 *
214	 * Description:
215	 *   Allocate DMA descriptor rings and buffers.
216	 *
217	 ****************************************************************************/
218	
219	static int alloc_dma(struct sg2000_eth_priv_s *priv)
220	{
221	  int i;
222	
223	  priv->tx_desc = kmm_memalign(16, TX_RING_SIZE *
224	                                sizeof(struct sg2000_dma_desc_s));
225	  priv->rx_desc = kmm_memalign(16, RX_RING_SIZE *
226	                                sizeof(struct sg2000_dma_desc_s));
227	
228	  if (!priv->tx_desc || !priv->rx_desc)
229	    {
230	      return -ENOMEM;
231	    }
232	
233	  memset(priv->tx_desc, 0, TX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
234	  memset(priv->rx_desc, 0, RX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
235	
236	  /* MMU-less: virtual address = physical address */
237	
238	  priv->tx_desc_phys = (uint32_t)(uintptr_t)priv->tx_desc;
239	  priv->rx_desc_phys = (uint32_t)(uintptr_t)priv->rx_desc;
240	
241	  for (i = 0; i < TX_RING_SIZE; i++)
242	    {
243	      priv->tx_buf[i] = kmm_memalign(4, TX_BUF_SIZE);
244	    }
245	
246	  for (i = 0; i < RX_RING_SIZE; i++)
247	    {
248	      priv->rx_buf[i] = kmm_memalign(4, RX_BUF_SIZE);
249	    }
250	
251	  return 0;
252	}
