254	/****************************************************************************
255	 * Name: init_desc_and_dma
256	 *
257	 * Description:
258	 *   Initialize descriptor rings and write DMA registers.
259	 *
260	 ****************************************************************************/
261	
262	static void init_desc_and_dma(struct sg2000_eth_priv_s *priv)
263	{
264	  uintptr_t base = priv->gmac_base;
265	  uintptr_t dma = base + DMA_CHAN_BASE;
266	  int i;
267	
268	  /* TX descriptors: clear all */
269	
270	  for (i = 0; i < TX_RING_SIZE; i++)
271	    {
272	      priv->tx_desc[i].des0 = 0;
273	      priv->tx_desc[i].des2 = (uint32_t)(uintptr_t)priv->tx_buf[i];
274	    }
275	
276	  /* RX descriptors: set OWN=1 (DMA can write) */
277	
278	  for (i = 0; i < RX_RING_SIZE; i++)
279	    {
280	      priv->rx_desc[i].des0 = DESC_OWN;
281	      priv->rx_desc[i].des1 = RX_BUF_SIZE;
282	      priv->rx_desc[i].des2 = (uint32_t)(uintptr_t)priv->rx_buf[i];
283	    }
284	
285	  priv->tx_cur = 0;
286	  priv->tx_dirty = 0;
287	  priv->rx_cur = 0;
288	
289	  /* Write DMA registers */
290	
291	  putreg32(DMA_SYS_DEFAULT, base + DMA_SYS_BUS_MODE);
292	  putreg32(TX_RING_SIZE - 1, dma + DMA_CHAN_TX_RING_LEN);
293	  putreg32(RX_RING_SIZE - 1, dma + DMA_CHAN_RX_RING_LEN);
294	  putreg32(priv->tx_desc_phys, dma + DMA_CHAN_TX_BASE_ADDR);
295	  putreg32(priv->rx_desc_phys, dma + DMA_CHAN_RX_BASE_ADDR);
296	  putreg32(DMA_INTR_DEFAULT_MASK, dma + DMA_CHAN_INTR_ENA);
297	}
