/****************************************************************************
 * Name: sg2000_eth_isr
 *
 * Description:
 *   Interrupt service routine.
 *   Source: dwmac4_lib.c:141-184
 *
 ****************************************************************************/

static int sg2000_eth_isr(int irq, void *context, void *arg)
{
  struct sg2000_eth_priv_s *priv = (struct sg2000_eth_priv_s *)arg;
  uintptr_t base = priv->gmac_base;
  uintptr_t dma = base + DMA_CHAN_BASE;
  uint32_t status;
  uint32_t intr_en;
  uint32_t mac;

  mac = getreg32(base + GMAC_INT_STATUS);
  if (mac)
    {
      putreg32(mac, base + GMAC_INT_STATUS);
    }

  intr_en = getreg32(dma + DMA_CHAN_INTR_ENA);
  status = getreg32(dma + DMA_CHAN_STATUS) & intr_en;

  if (!status)
    {
      return OK;
    }

  /* W1C clear */

  putreg32(status, dma + DMA_CHAN_STATUS);

  if (status & DMA_STATUS_NIS)
    {
      if (status & DMA_STATUS_RI)
        {
          netdev_rx_ready(&priv->dev);
        }

      if (status & DMA_STATUS_TI)
        {
          /* TX complete */
        }
    }

  if (status & DMA_STATUS_AIS)
    {
      printf("!! DMA Abnormal: 0x%08X\n", status);

      if (status & DMA_STATUS_RBU)
        {
          printf("   RX Buf Unavailable\n");
        }

      if (status & DMA_STATUS_TPS)
        {
          printf("   TX Stopped\n");
        }

      if (status & DMA_STATUS_FBE)
        {
          printf("   Fatal Bus Error\n");
        }
    }

  return OK;
}

/****************************************************************************
 * Name: sg2000_eth_rx
 *
 * Description:
 *   Receive a packet from DMA ring.
 *
 ****************************************************************************/

static int sg2000_eth_rx(struct sg2000_eth_priv_s *priv)
{
  struct sg2000_dma_desc_s *desc = &priv->rx_desc[priv->rx_cur];
  uint32_t status;
  int len;

  if (desc->des0 & DESC_OWN)
    {
      return 0;  /* DMA still owns it */
    }

  status = desc->des0;

  if (status & RX_DESC_ES)
    {
      goto refill;  /* Error packet, discard */
    }

  len = ((status >> RX_DESC_FL_SHIFT) & RX_DESC_FL_MASK) - 4;  /* Remove FCS */

  if (len > CONFIG_NET_ETH_PKTSIZE)
    {
      goto refill;
    }

  memcpy(priv->dev.d_buf, priv->rx_buf[priv->rx_cur], len);
  priv->dev.d_len = len;

refill:

  /* Return descriptor to DMA */

  desc->des0 = DESC_OWN;
  desc->des1 = RX_BUF_SIZE;

  priv->rx_cur = (priv->rx_cur + 1) & (RX_RING_SIZE - 1);

  rx_doorbell(priv);

  return (priv->dev.d_len > 0) ? 1 : 0;
}

