/****************************************************************************
 * Private Functions - Step 7: NuttX Netdev Callbacks
 ****************************************************************************/

/****************************************************************************
 * Name: sg2000_eth_ifup
 *
 * Description:
 *   Called when the network interface is brought up.
 *
 ****************************************************************************/

static int sg2000_eth_ifup(struct net_driver_s *dev)
{
  struct sg2000_eth_priv_s *priv =
      (struct sg2000_eth_priv_s *)dev->d_private;

  ephy_hardware_reset(priv->phy_base, priv->phy_top);
  dma_soft_reset(priv->gmac_base);
  init_desc_and_dma(priv);
  set_mac_addr(priv->gmac_base, priv->mac_addr);
  start_mac_and_dma(priv->gmac_base);
  rx_doorbell(priv);

  up_enable_irq(priv->irq);
  netdev_carrier_on(dev);

  return OK;
}

/****************************************************************************
 * Name: sg2000_eth_ifdown
 *
 * Description:
 *   Called when the network interface is brought down.
 *
 ****************************************************************************/

static int sg2000_eth_ifdown(struct net_driver_s *dev)
{
  struct sg2000_eth_priv_s *priv =
      (struct sg2000_eth_priv_s *)dev->d_private;
  uint32_t v;

  up_disable_irq(priv->irq);

  /* Stop TX DMA */

  v = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL);
  putreg32(v & ~DMA_TX_ST,
           priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL);

  /* Stop RX DMA */

  v = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);
  putreg32(v & ~DMA_RX_SR,
           priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);

  /* Disable MAC TX/RX */

  v = getreg32(priv->gmac_base + GMAC_CONFIG);
  putreg32(v & ~(GMAC_CONFIG_TE | GMAC_CONFIG_RE),
           priv->gmac_base + GMAC_CONFIG);

  netdev_carrier_off(dev);

  return OK;
}

/****************************************************************************
 * Name: sg2000_eth_txavail
 *
 * Description:
 *   Called when there is data to transmit.
 *
 ****************************************************************************/

static int sg2000_eth_txavail(struct net_driver_s *dev)
{
  struct sg2000_eth_priv_s *priv =
      (struct sg2000_eth_priv_s *)dev->d_private;

  if (dev->d_len > 0)
    {
      send_packet(priv, dev->d_buf, dev->d_len);
      dev->d_len = 0;
      NETDEV_TXPACKETS(dev);
    }

  return OK;
}

/****************************************************************************
 * Name: sg2000_eth_rmac
 *
 * Description:
 *   Called to receive packets (poll mode).
 *
 ****************************************************************************/

static int sg2000_eth_rmac(struct net_driver_s *dev)
{
  struct sg2000_eth_priv_s *priv =
      (struct sg2000_eth_priv_s *)dev->d_private;

  if (sg2000_eth_rx(priv))
    {
      NETDEV_RXPACKETS(dev);
    }

  return OK;
}

