84	/****************************************************************************
85	 * Private Functions - Step 2: DMA Software Reset
86	 ****************************************************************************/
87	
88	/****************************************************************************
89	 * Name: dma_soft_reset
90	 *
91	 * Description:
92	 *   Perform DMA software reset.
93	 *   Source: dwmac4_lib.c:15-26
94	 *
95	 ****************************************************************************/
96	
97	static int dma_soft_reset(uintptr_t gmac_base)
98	{
99	  uint32_t val;
100	  int timeout = 100000;
101	
102	  val = getreg32(gmac_base + DMA_BUS_MODE);
103	  putreg32(val | DMA_SFT_RESET, gmac_base + DMA_BUS_MODE);
104	
105	  do
106	    {
107	      val = getreg32(gmac_base + DMA_BUS_MODE);
108	      if (!(val & DMA_SFT_RESET))
109	        {
110	          printf("DMA reset PASS\n");
111	          return 0;
112	        }
113	
114	      up_udelay(10);
115	    }
116	  while (--timeout > 0);
117	
118	  printf("FAIL: DMA reset timeout\n");
119	  return -1;
120	}
