210	/****************************************************************************
211	 * Private Functions - Step 4: Allocate DMA Descriptor Rings
212	 ****************************************************************************/
213	
214	/****************************************************************************
215	 * Name: alloc_dma
216	 *
217	 * Description:
218	 *   Allocate DMA descriptor rings and buffers.
219	 *
220	 ****************************************************************************/
221	
222	static int alloc_dma(struct sg2000_eth_priv_s *priv)
223	{
224	  int i;
225	
226	  priv->tx_desc = kmm_memalign(16, TX_RING_SIZE *
227	                                sizeof(struct sg2000_dma_desc_s));
228	  priv->rx_desc = kmm_memalign(16, RX_RING_SIZE *
229	                                sizeof(struct sg2000_dma_desc_s));
230	
231	  if (!priv->tx_desc || !priv->rx_desc)
232	    {
233	      return -ENOMEM;
234	    }
235	
236	  memset(priv->tx_desc, 0, TX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
237	  memset(priv->rx_desc, 0, RX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
238	
239	  /* MMU-less: virtual address = physical address */
240	
241	  priv->tx_desc_phys = (uint32_t)(uintptr_t)priv->tx_desc;
242	  priv->rx_desc_phys = (uint32_t)(uintptr_t)priv->rx_desc;
243	
244	  for (i = 0; i < TX_RING_SIZE; i++)
245	    {
246	      priv->tx_buf[i] = kmm_memalign(4, TX_BUF_SIZE);
247	    }
248	
249	  for (i = 0; i < RX_RING_SIZE; i++)
250	    {
251	      priv->rx_buf[i] = kmm_memalign(4, RX_BUF_SIZE);
252	    }
253	
254	  return 0;
255	}
256	
257	/****************************************************************************
258	 * Name: init_desc_and_dma
259	 *
260	 * Description:
261	 *   Initialize descriptor rings and write DMA registers.
262	 *
263	 ****************************************************************************/
264	
265	static void init_desc_and_dma(struct sg2000_eth_priv_s *priv)
266	{
267	  uintptr_t base = priv->gmac_base;
268	  uintptr_t dma = base + DMA_CHAN_BASE;
269	  int i;
270	
271	  /* TX descriptors: clear all */
272	
273	  for (i = 0; i < TX_RING_SIZE; i++)
274	    {
275	      priv->tx_desc[i].des0 = 0;
276	      priv->tx_desc[i].des2 = (uint32_t)(uintptr_t)priv->tx_buf[i];
277	    }
278	
279	  /* RX descriptors: set OWN=1 (DMA can write) */
280	
281	  for (i = 0; i < RX_RING_SIZE; i++)
282	    {
283	      priv->rx_desc[i].des0 = DESC_OWN;
284	      priv->rx_desc[i].des1 = RX_BUF_SIZE;
285	      priv->rx_desc[i].des2 = (uint32_t)(uintptr_t)priv->rx_buf[i];
286	    }
287	
288	  priv->tx_cur = 0;
289	  priv->tx_dirty = 0;
290	  priv->rx_cur = 0;
291	
292	  /* Write DMA registers */
293	
294	  putreg32(DMA_SYS_DEFAULT, base + DMA_SYS_BUS_MODE);
295	  putreg32(TX_RING_SIZE - 1, dma + DMA_CHAN_TX_RING_LEN);
296	  putreg32(RX_RING_SIZE - 1, dma + DMA_CHAN_RX_RING_LEN);
297	  putreg32(priv->tx_desc_phys, dma + DMA_CHAN_TX_BASE_ADDR);
298	  putreg32(priv->rx_desc_phys, dma + DMA_CHAN_RX_BASE_ADDR);
299	  putreg32(DMA_INTR_DEFAULT_MASK, dma + DMA_CHAN_INTR_ENA);
300	}
