302	/****************************************************************************
303	 * Private Functions - Step 5: Configure MAC + Start DMA + Send Test Packet
304	 ****************************************************************************/
305	
306	/****************************************************************************
307	 * Name: set_mac_addr
308	 *
309	 * Description:
310	 *   Set MAC address in hardware.
311	 *   Source: dwmac4_lib.c:187-201
312	 *
313	 ****************************************************************************/
314	
315	static void set_mac_addr(uintptr_t gmac_base, const uint8_t *mac)
316	{
317	  uint32_t hi;
318	  uint32_t lo;
319	
320	  hi = (mac[5] << 8) | mac[4] | GMAC_HI_REG_AE;
321	  lo = (mac[3] << 24) | (mac[2] << 16) | (mac[1] << 8) | mac[0];
322	
323	  putreg32(hi, gmac_base + GMAC_ADDR_HIGH(0));
324	  putreg32(lo, gmac_base + GMAC_ADDR_LOW(0));
325	}
326	
327	/****************************************************************************
328	 * Name: start_mac_and_dma
329	 *
330	 * Description:
331	 *   Start MAC and DMA.
332	 *   Source: dwmac4_core.c:48 + dwmac4_lib.c:38-73
333	 *
334	 ****************************************************************************/
335	
336	static void start_mac_and_dma(uintptr_t gmac_base)
337	{
338	  uintptr_t dma = gmac_base + DMA_CHAN_BASE;
339	  uint32_t v;
340	
341	  v = GMAC_CORE_INIT | GMAC_CONFIG_FES | GMAC_CONFIG_DM;
342	  putreg32(v, gmac_base + GMAC_CONFIG);
343	
344	  putreg32(GMAC_FILTER_HMC | GMAC_FILTER_PM,
345	           gmac_base + GMAC_PACKET_FILTER);
346	
347	  putreg32(GMAC_INT_DEFAULT, gmac_base + GMAC_INT_EN);
348	
349	  /* Enable TX and RX */
350	
351	  v = getreg32(gmac_base + GMAC_CONFIG);
352	  putreg32(v | GMAC_CONFIG_TE | GMAC_CONFIG_RE, gmac_base + GMAC_CONFIG);
353	
354	  /* Start TX DMA */
355	
356	  v = getreg32(dma + DMA_CHAN_TX_CONTROL);
357	  putreg32(v | DMA_TX_ST, dma + DMA_CHAN_TX_CONTROL);
358	
359	  /* Start RX DMA */
360	
361	  v = getreg32(dma + DMA_CHAN_RX_CONTROL);
362	  putreg32(v | DMA_RX_SR, dma + DMA_CHAN_RX_CONTROL);
363	}
