365	/****************************************************************************
366	 * Name: tx_doorbell
367	 *
368	 * Description:
369	 *   Update TX Tail Pointer (doorbell).
370	 *   Source: dwmac4_lib.c:33-36
371	 *
372	 ****************************************************************************/
373	
374	static void tx_doorbell(struct sg2000_eth_priv_s *priv)
375	{
376	  uint32_t tail = priv->tx_desc_phys +
377	                  priv->tx_cur * sizeof(struct sg2000_dma_desc_s);
378	
379	  putreg32(tail, priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_END_ADDR);
380	}
381	
382	/****************************************************************************
383	 * Name: rx_doorbell
384	 *
385	 * Description:
386	 *   Update RX Tail Pointer (doorbell).
387	 *   Source: dwmac4_lib.c:28-31
388	 *
389	 ****************************************************************************/
390	
391	static void rx_doorbell(struct sg2000_eth_priv_s *priv)
392	{
393	  uint32_t tail = priv->rx_desc_phys +
394	                  priv->rx_cur * sizeof(struct sg2000_dma_desc_s);
395	
396	  putreg32(tail, priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_END_ADDR);
397	}
