399	/****************************************************************************
400	 * Name: send_packet
401	 *
402	 * Description:
403	 *   Send a packet via DMA.
404	 *
405	 ****************************************************************************/
406	
407	static int send_packet(struct sg2000_eth_priv_s *priv,
408	                       const uint8_t *data, int len)
409	{
410	  unsigned int idx = priv->tx_cur;
411	  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
412	
413	  if (desc->des0 & DESC_OWN)
414	    {
415	      printf("TX ring full\n");
416	      return -EBUSY;
417	    }
418	
419	  memcpy(priv->tx_buf[idx], data, len);
420	
421	  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
422	  desc->des1 = len;
423	  desc->des0 = DESC_OWN | TX_DESC_FS | TX_DESC_LS | TX_DESC_IC | len;
424	
425	  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);
426	
427	  tx_doorbell(priv);
428	  return 0;
429	}
