625	/****************************************************************************
626	 * Private Functions - Step 7: NuttX Netdev Callbacks
627	 ****************************************************************************/
628	
629	/****************************************************************************
630	 * Name: sg2000_eth_ifup
631	 *
632	 * Description:
633	 *   Called when the network interface is brought up.
634	 *
635	 ****************************************************************************/
636	
637	static int sg2000_eth_ifup(struct net_driver_s *dev)
638	{
639	  struct sg2000_eth_priv_s *priv =
640	      (struct sg2000_eth_priv_s *)dev->d_private;
641	
642	  ephy_hardware_reset(priv->phy_base, priv->phy_top);
643	  dma_soft_reset(priv->gmac_base);
644	  init_desc_and_dma(priv);
645	  set_mac_addr(priv->gmac_base, priv->mac_addr);
646	  start_mac_and_dma(priv->gmac_base);
647	  rx_doorbell(priv);
648	
649	  up_enable_irq(priv->irq);
650	  netdev_carrier_on(dev);
651	
652	  return OK;
653	}
654	
655	/****************************************************************************
656	 * Name: sg2000_eth_ifdown
657	 *
658	 * Description:
659	 *   Called when the network interface is brought down.
660	 *
661	 ****************************************************************************/
662	
663	static int sg2000_eth_ifdown(struct net_driver_s *dev)
664	{
665	  struct sg2000_eth_priv_s *priv =
666	      (struct sg2000_eth_priv_s *)dev->d_private;
667	  uint32_t v;
668	
669	  up_disable_irq(priv->irq);
670	
671	  /* Stop TX DMA */
672	
673	  v = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL);
674	  putreg32(v & ~DMA_TX_ST,
675	           priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL);
676	
677	  /* Stop RX DMA */
678	
679	  v = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);
680	  putreg32(v & ~DMA_RX_SR,
681	           priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);
682	
683	  /* Disable MAC TX/RX */
684	
685	  v = getreg32(priv->gmac_base + GMAC_CONFIG);
686	  putreg32(v & ~(GMAC_CONFIG_TE | GMAC_CONFIG_RE),
687	           priv->gmac_base + GMAC_CONFIG);
688	
689	  netdev_carrier_off(dev);
690	
691	  return OK;
692	}
