742	/****************************************************************************
743	 * Name: sg2000_eth_initialize
744	 *
745	 * Description:
746	 *   Initialize the SG2000 ethernet driver.
747	 *
748	 ****************************************************************************/
749	
750	int sg2000_eth_initialize(void)
751	{
752	  struct sg2000_eth_priv_s *priv = &g_eth_priv;
753	  int ret;
754	  uint16_t id1;
755	  uint16_t id2;
756	  uint32_t phy_id;
757	  uint32_t r1;
758	  uint32_t r2;
759	
760	  memset(priv, 0, sizeof(*priv));
761	  priv->gmac_base = SG2000_GMAC_BASE;
762	  priv->phy_base = SG2000_EPHY_BASE;
763	  priv->phy_top = SG2000_EPHY_TOP;
764	
765	  /* Set test MAC address */
766	
767	  priv->mac_addr[0] = 0x02;
768	  priv->mac_addr[1] = 0x00;
769	  priv->mac_addr[2] = 0x00;
770	  priv->mac_addr[3] = 0x00;
771	  priv->mac_addr[4] = 0x00;
772	  priv->mac_addr[5] = 0x01;
773	
774	  /* Step 1: Verify register readability */
775	
776	  ret = test_read_hw_feature(priv->gmac_base);
777	  if (ret < 0)
778	    {
779	      return ret;
780	    }
781	
782	  /* Step 2: DMA software reset */
783	
784	  ret = dma_soft_reset(priv->gmac_base);
785	  if (ret < 0)
786	    {
787	      return ret;
788	    }
789	
790	  /* Step 3: EPHY reset + MDIO read PHY ID */
791	
792	  ephy_hardware_reset(priv->phy_base, priv->phy_top);
793	
794	  id1 = mdio_read(priv->gmac_base, 0, 2);
795	  id2 = mdio_read(priv->gmac_base, 0, 3);
796	  phy_id = (id1 << 16) | id2;
797	
798	  printf("PHY ID = 0x%08X (expect 0x00435649)\n", phy_id);
799	
800	  if (phy_id == CVITEK_PHY_ID)
801	    {
802	      printf("PHY ID PASS\n");
803	    }
804	  else if (phy_id == 0xffffffff)
805	    {
806	      printf("FAIL: PHY not responding\n");
807	      return -1;
808	    }
809	  else
810	    {
811	      printf("FAIL: Unexpected PHY ID\n");
812	      return -1;
813	    }
814	
815	  /* Step 4: Allocate DMA descriptor rings + write DMA registers */
816	
817	  ret = alloc_dma(priv);
818	  if (ret < 0)
819	    {
820	      printf("FAIL: alloc_dma\n");
821	      return ret;
822	    }
823	
824	  init_desc_and_dma(priv);
825	
826	  /* Readback verification */
827	
828	  r1 = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_BASE_ADDR);
829	  r2 = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_RING_LEN);
830	
831	  printf("Readback TX_BASE: 0x%08X (expect 0x%08X) %s\n",
832	         r1, priv->tx_desc_phys,
833	         r1 == priv->tx_desc_phys ? "OK" : "FAIL");
834	  printf("Readback TX_LEN:  %d (expect %d) %s\n",
835	         r2, TX_RING_SIZE - 1,
836	         r2 == (TX_RING_SIZE - 1) ? "OK" : "FAIL");
837	
838	  if (r1 != priv->tx_desc_phys || r2 != (TX_RING_SIZE - 1))
839	    {
840	      return -1;
841	    }
842	
843	  /* Step 5: Configure MAC + start DMA + send test packet */
844	
845	  set_mac_addr(priv->gmac_base, priv->mac_addr);
846	  start_mac_and_dma(priv->gmac_base);
847	  rx_doorbell(priv);
848	
849	  printf("Sending test ARP packet...\n");
850	  ret = send_test_arp(priv);
851	  if (ret < 0)
852	    {
853	      printf("FAIL: send_test_arp\n");
854	      return ret;
855	    }
856	
857	  printf("Test ARP sent. Check with tcpdump on PC.\n");
858	
859	  /* Step 6: Register ISR */
860	
861	  priv->irq = SG2000_IRQ_GMAC;
862	  irq_attach(priv->irq, sg2000_eth_isr, priv);
863	  up_enable_irq(priv->irq);
864	
865	  printf("IRQ %d enabled. Waiting for packets...\n", priv->irq);
866	
867	  /* Step 7: Register netdev */
868	
869	  priv->dev.d_buf = kmm_zalloc(CONFIG_NET_ETH_PKTSIZE);
870	  if (!priv->dev.d_buf)
871	    {
872	      printf("FAIL: alloc d_buf\n");
873	      return -ENOMEM;
874	    }
875	
876	  priv->dev.d_ifup = sg2000_eth_ifup;
877	  priv->dev.d_ifdown = sg2000_eth_ifdown;
878	  priv->dev.d_txavail = sg2000_eth_txavail;
879	  priv->dev.d_rmac = sg2000_eth_rmac;
880	  priv->dev.d_private = priv;
881	
882	  ret = netdev_register(&priv->dev, NET_LL_ETHERNET);
883	  if (ret < 0)
884	    {
885	      printf("FAIL: netdev_register: %d\n", ret);
886	      return ret;
887	    }
888	
889	  printf("SG2000 Ethernet driver registered as eth0\n");
890	
891	  return OK;
892	}
